import Foundation

/// Bridge between the classical blemish detector and the learned scorer.
///
/// Deliberately additive: nothing in `RetouchEngine` changes until the first
/// Xcode build is green, so this file can never regress the shipping path.
/// Wiring it in is a one-line change where the detector has its candidate set:
///
///     detection.spots = BlemishModelBridge.rescore(detection.spots,
///                                                  features: detection.featureRows)
///
/// The scaler/weights live in `BlemishLearnedModel.swift` (generated by
/// `tools/model_lab/train_blemish.py`), so retraining never touches this file.
enum BlemishModelBridge {
    /// Fraction of the classical confidence that the learned model contributes
    /// when it is confident either way. 0 = pure classical, 1 = pure learned.
    static let learnedWeight: Float = 0.65

    /// Re-scores candidates with the learned model.
    /// - Parameters:
    ///   - spots: classical candidates, ordered by classical confidence.
    ///   - features: one row per candidate, same order, feature order must match
    ///     `BlemishLearnedModel.weights` (dL, dA, dB, log1, log2, log3, grad, ringStd, dE).
    /// - Returns: candidates whose learned probability clears the threshold, with
    ///   the blended score, sorted descending. Rows that are missing or malformed
    ///   keep their classical score (never dropped silently).
    static func rescore(_ spots: [BlemishSpot], features: [[Float]]) -> [BlemishSpot] {
        guard !spots.isEmpty else { return [] }
        var out: [BlemishSpot] = []
        out.reserveCapacity(spots.count)
        for (index, spot) in spots.enumerated() {
            guard index < features.count,
                  features[index].count == BlemishLearnedModel.featureCount else {
                out.append(spot)
                continue
            }
            let learned = Double(BlemishLearnedModel.probability(features[index]))
            let blended = Double(learnedWeight) * learned + Double(1 - learnedWeight) * spot.score
            if learned < 0.5 { continue }
            var updated = spot
            updated.score = blended
            out.append(updated)
        }
        return out.sorted { $0.score > $1.score }
    }

    /// Operator-facing summary used by the QC panel.
    static func summary(learnedKept: Int, classicalCount: Int) -> String {
        guard classicalCount > 0 else { return "瑕疵：本图未发现候选" }
        let dropped = max(0, classicalCount - learnedKept)
        return "瑕疵：候选 \(classicalCount) 处，模型确认 \(learnedKept) 处，剔除 \(dropped) 处（雀斑/毛孔/阴影）"
    }
}
